    "content": "// src/matrix.ts

export function identity(n: number): number[][] {
  const matrix: number[][] = [];
  for (let i = 0; i < n; i++) {
    const row: number[] = [];
    for (let j = 0; j < n; j++) {
      row.push(i === j ? 1 : 0);
    }
    matrix.push(row);
  }
  return matrix;
}

export function transpose(matrix: number[][]): number[][] {
  const transposed: number[][] = [];
  for (let i = 0; i < matrix[0].length; i++) {
    const row: number[] = [];
    for (let j = 0; j < matrix.length; j++) {
      row.push(matrix[j][i]);
    }
    transposed.push(row);
  }
  return transposed;
}

export function multiply(matrixA: number[][], matrixB: number[][]): number[][] {
  const result: number[][] = [];
  for (let i = 0; i < matrixA.length; i++) {
    const row: number[] = [];
    for (let j = 0; j < matrixB[0].length; j++) {
      let sum = 0;
      for (let k = 0; k < matrixB.length; k++) {
        sum += matrixA[i][k] * matrixB[k][j];
      }
      row.push(sum);
    }
    result.push(row);
  }
  return result;
}

export function multiplyVector(matrix: number[][], vector: number[]): number[] {
  const result: number[] = [];
  for (let i = 0; i < matrix.length; i++) {
    let sum = 0;
    for (let j = 0; j < vector.length; j++) {
      sum += matrix[i][j] * vector[j];
    }
    result.push(sum);
  }
  return result;
}

export function solve(matrix: number[][], vector: number[]): number[] {
  const augmentedMatrix: number[][] = matrix.map((row, i) => [...row, vector[i]]);
  const n = matrix.length;
  for (let i = 0; i < n; i++) {
    if (augmentedMatrix[i][i] === 0) {
      for (let j = i + 1; j < n; j++) {
        if (augmentedMatrix[j][i] !== 0) {
          const temp = augmentedMatrix[i];
          augmentedMatrix[i] = augmentedMatrix[j];
          augmentedMatrix[j] = temp;
          break;
        }
      }
    }
    const pivot = augmentedMatrix[i][i];
    if (pivot === 0) {
      throw new Error('Singular matrix');
    }
    for (let j = i; j < n + 1; j++) {
      augmentedMatrix[i][j] /= pivot;
    }
    for (let j = 0; j < n; j++) {
      if (j !== i) {
        const factor = augmentedMatrix[j][i];
        for (let k = i; k < n + 1; k++) {
          augmentedMatrix[j][k] -= factor * augmentedMatrix[i][k];
        }
      }
    }
  }
  const solution: number[] = [];
  for (let i = 0; i < n; i++) {
    solution.push(augmentedMatrix[i][n]);
  }
  return solution;
}"
